<script setup>
import {Head,useForm} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import PageBanner from '../../Components/PageBanner.vue';
defineOptions({layout:AppLayout}); const p=defineProps({refill:Object,role:String}); const localNow=()=>{const d=new Date(); return new Date(d-Date.parse(d.toISOString().slice(0,10)+'T00:00:00Z')+new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime()).toISOString().slice(0,16)}; const revision=useForm({line_id:'',quantity:'',reason:''}); const shipment=useForm({document_no:'',expedition:'',shipped_at:localNow(),lines:p.refill.lines.filter(x=>Number(x.outstanding)>0).map(x=>({enabled:true,refill_line_id:x.id,quantity:x.outstanding}))}); const closing=useForm({reason:''}); const submitShipment=()=>shipment.transform(d=>({...d,lines:d.lines.filter(x=>x.enabled).map(({refill_line_id,quantity})=>({refill_line_id,quantity}))})).post(p.refill.shipment_url); const review=(r,approve)=>useForm({approve,note:approve?'Disetujui':'Ditolak'}).post(r.review_url); const terminal=['COMPLETED','CLOSED_PARTIAL','CANCELLED'].includes(p.refill.status);
</script>
<template><Head :title="refill.number"/><div class="units-page"><PageBanner :title="refill.number" :description="`${refill.vendor} · ${refill.status}`" icon="truck"/><div v-if="Object.keys(revision.errors).length||Object.keys(shipment.errors).length||Object.keys(closing.errors).length" class="field-error" role="alert">Tindakan belum berhasil. Periksa status, quantity, dan data wajib.</div><section class="surface-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Barang</th><th>Diminta</th><th>Dikirim</th><th>Diterima</th><th>Outstanding</th><th>Revisi</th></tr></thead><tbody><tr v-for="l in refill.lines" :key="l.id"><td>{{l.item}}</td><td>{{l.quantity}}</td><td>{{l.shipped}}</td><td>{{l.received}}</td><td>{{l.outstanding}}</td><td><div v-for="r in l.revisions" :key="r.id">{{r.quantity}} · {{r.status}} · {{r.reason}} <template v-if="role==='admin'&&r.status==='PENDING'&&!terminal"><button class="text-button" @click="review(r,true)">Setujui</button><button class="text-button" @click="review(r,false)">Tolak</button></template></div><span v-if="!l.revisions.length">—</span></td></tr></tbody></table></div></section><section class="surface-card"><h2>Riwayat proses</h2><p>Pengiriman: {{refill.shipments.length}} · Receipt: {{refill.receipts.length}}</p></section><section v-if="role==='vendor'&&!terminal" class="surface-card form-card"><form class="form-card__body form-stack" @submit.prevent="revision.post(refill.revision_url)"><h2>Usulkan revisi</h2><select v-model="revision.line_id" class="form-input" required><option value="">Pilih barang</option><option v-for="l in refill.lines" :key="l.id" :value="l.id">{{l.item}}</option></select><input v-model="revision.quantity" class="form-input" type="number" min="0.0001" step="0.0001" placeholder="Quantity mampu dikirim" required/><textarea v-model="revision.reason" class="form-input" placeholder="Alasan" required/><button class="button button--secondary">Kirim revisi</button></form><form class="form-card__body form-stack" @submit.prevent="submitShipment"><h2>Tandai dikirim</h2><input v-model="shipment.document_no" class="form-input" placeholder="Nomor DO/surat jalan" required/><input v-model="shipment.expedition" class="form-input" placeholder="Ekspedisi"/><input v-model="shipment.shipped_at" class="form-input" type="datetime-local" required/><div v-for="x in shipment.lines" :key="x.refill_line_id" class="form-grid"><label><input v-model="x.enabled" type="checkbox"/> {{refill.lines.find(l=>l.id===x.refill_line_id)?.item}}</label><input v-model="x.quantity" class="form-input" type="number" min="0.0001" step="0.0001" :disabled="!x.enabled" required/></div><button class="button button--primary" :disabled="!shipment.lines.some(x=>x.enabled)">Simpan pengiriman</button></form></section><section v-if="role==='admin'&&!terminal" class="surface-card form-card"><form class="form-card__body form-stack" @submit.prevent="closing.post(refill.close_url)"><h2>Tutup sisa refill</h2><textarea v-model="closing.reason" class="form-input" placeholder="Alasan wajib" required/><button class="button button--danger">Tutup Sisa</button></form></section></div></template>
